<?php include '../includes/header.php';$u=user();if(is_admin()){$r=mysqli_query($conn,"SELECT t.*,GROUP_CONCAT(u.name SEPARATOR ', ') assignees FROM work_tasks t LEFT JOIN task_assignees ta ON ta.task_id=t.id LEFT JOIN users u ON u.id=ta.user_id GROUP BY t.id ORDER BY t.id DESC");}else{$s=mysqli_prepare($conn,"SELECT DISTINCT t.* FROM work_tasks t JOIN task_assignees ta ON ta.task_id=t.id WHERE ta.user_id=? OR EXISTS(SELECT 1 FROM task_authorities a WHERE a.task_id=t.id AND a.user_id=?) ORDER BY t.id DESC");mysqli_stmt_bind_param($s,'ii',$u['id'],$u['id']);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);}?>
<div class="page-head"><div><p class="eyebrow">WORK MANAGEMENT</p><h1>Work & Tasks</h1><p class="muted">Assignments, progress updates and completion tracking.</p></div><?php if(is_admin()):?><a class="btn primary" href="create.php">+ Assign Work</a><?php endif;?></div>
<div class="card table-wrap"><table><tr><th>Title</th><th>Kind</th><th>Priority</th><th>Status</th><th>Progress</th><th>Due</th><?php if(is_admin()):?><th>Assignees</th><?php endif;?></tr><?php while($x=mysqli_fetch_assoc($r)):?><tr><td><a href="view.php?id=<?=$x['id']?>"><?=e($x['title'])?></a></td><td><?=e($x['kind'])?></td><td><span class="pill <?=e($x['priority'])?>"><?=e($x['priority'])?></span></td><td><?=e($x['status'])?></td><td><div class="progress"><span style="width:<?=min(100,(int)$x['progress_percent'])?>%"></span></div><?=e($x['progress_percent'])?>%</td><td><?=e($x['due_date']?:'—')?></td><?php if(is_admin()):?><td><?=e($x['assignees']?:'—')?></td><?php endif;?></tr><?php endwhile;?></table></div><?php include '../includes/footer.php';?>
